sys_script_include.script:
var AccessGovernanceRevokeProcessor = Class.create();
AccessGovernanceRevokeProcessor.prototype = {
    initialize: function() {},
    processRequest: function(userId, action, groupsList) {
        var res = {
            status: 'success',
            action: action,
            result: ''
        };
        // your branching logic here
        if (action == 'Offboard user') {
            var offboard = new global.AccessGovernanceGlobalHelper();
            var r = offboard.offboardUser(userId);
            res.result = r;
        } else if (action == 'Revoke groups') {
            var revoke = new global.AccessGovernanceGlobalHelper();
            var groupArray = groupsList.split(',');
            var resultarr = [];
            for (var i = 0; i < groupArray.length; i++) {
                var rr = revoke.revokeGroupMembership(userId, groupArray[i]);
                resultarr.push(rr);
            }
            res.results = resultarr;

        } else if (action == 'Review') {
            // No automated action for Review — security context already
            // captured at request-creation time via AccessGovernanceUtils

        } else {
            res.status = 'error';
            res.message = 'Unrecognized action: ' + action;
        }
        return res;
    },

    type: 'AccessGovernanceRevokeProcessor'
};
